require("../frontend.js"),require("../../stripe-payment.js");let renderBlock=e=>{document.body.innerHTML=`
		<div class="srfm-multi-choice-block">
			<div class="srfm-multi-choice-single">
				<input class="srfm-input-multi-choice-single" option-value="149" />
				<div class="srfm-option-container">
					<label data-option-text="Early Bird">Frühbucher</label>
				</div>
			</div>
			<input class="srfm-input-multi-choice-hidden" value="${e}" />
		</div>`;e=document.querySelector("label");return Object.defineProperty(e,"innerText",{value:e.textContent}),{block:document.querySelector(".srfm-multi-choice-block"),hidden:document.querySelector(".srfm-input-multi-choice-hidden")}};describe("getMultiChoiceAmount",()=>{it("matches the submitted value, not the translated label",()=>{var{block:e,hidden:t}=renderBlock("Early Bird");expect(window.srfmPaymentUtility.getMultiChoiceAmount(e,t)).toBe(149)}),it("ignores a value that only matches the visible label",()=>{var{block:e,hidden:t}=renderBlock("Frühbucher");expect(window.srfmPaymentUtility.getMultiChoiceAmount(e,t)).toBe(0)})});